def _capability_unavailable(
    capability_id: str,
    *,
    message: str,
    impact: str,
    repair_action: str,
) -> HTTPException:
    return HTTPException(
        status_code=501,
        detail={
            "error": "capability_unavailable",
            "capability_id": capability_id,
            "detail": message,
            "impact": impact,
            "repair_action": repair_action,
            "retryable": False,
        },
    )


