_TASK_MEDIA_HANDLERS = {}


def _exact_edit_access(task_id, request, *, write=False):
    workspace_id = current_workspace_id(request)
    task = _creation_task_or_404(workspace_id, task_id)
    member_id = _assistant_member_id(request, workspace_id)
    if not _content_visible(request, workspace_id, task.visibility, task.owner_user_id):
        raise HTTPException(status_code=404, detail="creation task not found")
    if write and task.owner_user_id and task.owner_user_id != member_id:
        raise HTTPException(status_code=403, detail="当前成员不能修改此任务")
    return task, member_id


def _prepare_exact_edit_request(task_id, request, payload):
    envelope = payload.model_fields_set & EXACT_EDIT_ENVELOPE_FIELDS
    if not envelope:
        return payload, None  # Existing precise GUI calls keep their protocol.
    task, member_id = _exact_edit_access(task_id, request, write=True)
    version = production_repo.get_timeline_version(task.workspace_id, task.current_timeline_version_id) if task.current_timeline_version_id else None
    if not {"expected_timeline_version_id", "expected_timeline_sequence"} <= payload.model_fields_set:
        raise HTTPException(status_code=422, detail="类型化请求须绑定期望时间线版本和序号")
    if (payload.expected_timeline_version_id, payload.expected_timeline_sequence) != (task.current_timeline_version_id, version.sequence if version else 0):
        raise HTTPException(status_code=409, detail="时间线已变化，请重新读取当前任务")
    source = {"workspace_id": task.workspace_id, "task_id": task_id, "member_id": member_id,
              "request_id": str(payload.request_id) if payload.request_id else None,
              "expected_timeline_version_id": payload.expected_timeline_version_id,
              "expected_timeline_sequence": payload.expected_timeline_sequence}
    actor = _request_permit_actor(request, task.workspace_id) if auth_context.enabled else CreationExecutionActor(task.workspace_id, member_id)
    if actor is not None:
        source["actor_identity"] = actor.identity_payload()
    if payload.assistant_turn_id:
        try:
            origin = conversation_repo.task_turn_source(str(payload.assistant_turn_id), task.workspace_id, member_id, task_id)
        except ValueError as exc:
            raise HTTPException(status_code=409, detail=str(exc)) from exc
        snapshot = origin["context"].get("target_snapshot", {})
        if (snapshot.get("timeline_version_id"), snapshot.get("timeline_sequence")) != (task.current_timeline_version_id, version.sequence if version else 0):
            raise HTTPException(status_code=409, detail="助手轮次的目标版本已失效")
        source.update(assistant_turn_id=str(payload.assistant_turn_id), conversation_id=origin["conversation_id"], raw_command=origin["raw_command"])
    clean = CreationTaskExactEditRequest.model_validate(payload.model_dump(mode="json", exclude_unset=True, exclude=EXACT_EDIT_ENVELOPE_FIELDS))
    source["action"] = clean.model_dump(mode="json", exclude_unset=True)
    source["source_facts"] = _exact_edit_source_facts(task, clean, request)
    return clean, source


def _exact_edit_source_facts(task, payload, request):
    """Bind the actual authorized material revision without exposing host paths."""
    if payload.clip_id is None:
        return []
    montage = creation_task_montage_plan_from_payload(production_repo.get_creation_task_montage_plan(task.workspace_id, task.id))
    clip = next((item for item in montage.clips if item.id == payload.clip_id), None)
    if clip is None:
        raise HTTPException(status_code=404, detail="当前任务镜头不存在")
    pairs = [(clip.asset_id, clip.segment_id)] if not clip.person_render_id else []
    if payload.asset_id is not None and payload.segment_id is not None:
        pairs.append((payload.asset_id, payload.segment_id))
    facts = []
    for asset_id, segment_id in dict.fromkeys(pairs):
        try:
            asset = production_repo.get_asset(task.workspace_id, asset_id)
            if not _content_visible(request, task.workspace_id, asset.visibility, asset.owner_user_id):
                raise HTTPException(status_code=403, detail="当前成员不能使用该镜头素材")
            segment = next(item for item in asset.segments if item.id == segment_id)
            reference = production_repo.workspace_media_reference_for_asset(task.workspace_id, asset.id)
            path = production_repo.resolve_clip_media_reference(task.workspace_id, asset.id, reference)
            stat = path.stat()
        except (KeyError, StopIteration, OSError, MediaAuthorityError) as exc:
            raise HTTPException(status_code=409, detail="镜头来源或使用状态已失效") from exc
        facts.append({"asset_id": asset_id, "segment_id": segment_id, "reference": reference,
            "modified_at": asset.modified_at.isoformat(), "start_seconds": segment.start_seconds, "end_seconds": segment.end_seconds,
            "size": stat.st_size, "mtime_ns": stat.st_mtime_ns, "ctime_ns": stat.st_ctime_ns,
            "inode": stat.st_ino, "device": stat.st_dev})
    return facts


def _claim_edit_request(task, member_id, request_id, phase, inputs):
    identity = media_digest([task.workspace_id, member_id, str(request_id), phase])
    event_id = f"event_edit_request_{identity}"
    digest = media_digest([task.id, inputs])
    with production_repo._connect() as conn:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute("SELECT payload_json FROM task_events WHERE id=?", (event_id,)).fetchone()
        if row:
            previous = json.loads(row["payload_json"])
            if previous["input_digest"] != digest:
                raise HTTPException(status_code=409, detail="请求身份已绑定不同编辑输入")
            return event_id, False
        production_repo.append_task_event(TaskEvent(id=event_id, workspace_id=task.workspace_id,
            task_id=task.id, job_id=None, event_type="edit_request_claimed",
            payload={"member_id": member_id, "request_id": str(request_id), "phase": phase,
                     "input_digest": digest, "inputs": inputs}, created_at=utc_now()), connection=conn)
    return event_id, True


def _save_edit_request_result(task, event_id, result):
    status = result.status_code if isinstance(result, JSONResponse) else 200
    content = json.loads(result.body) if isinstance(result, JSONResponse) else result.model_dump(mode="json")
    production_repo.append_task_event(TaskEvent(id=event_id + "_result", workspace_id=task.workspace_id,
        task_id=task.id, job_id=None, event_type="edit_request_result",
        payload={"status_code": status, "response": content}, created_at=utc_now()))
    _wake_assistant_continuations()


def _read_edit_request_result(task, event_id):
    try:
        event = production_repo.get_task_event(task.workspace_id, event_id + "_result")
    except KeyError:
        return None
    return JSONResponse(status_code=event.payload["status_code"], content=event.payload["response"])


@app.get("/api/creation-tasks/{task_id}/assistant/edit-requests/{request_id}")
def get_exact_edit_request_result(task_id: str, request_id: UUID, request: Request, phase: Literal["preview", "apply", "script", "observation"] = "preview"):
    task, member_id = _exact_edit_access(task_id, request, write=True)
    event_id = "event_edit_request_" + media_digest([task.workspace_id, member_id, str(request_id), phase])
    try:
        event = production_repo.get_task_event(task.workspace_id, event_id)
    except KeyError as exc:
        raise HTTPException(status_code=404, detail="编辑请求不存在") from exc
    if event.task_id != task_id:
        raise HTTPException(status_code=404, detail="编辑请求不存在")
    inputs = event.payload["inputs"]
    if phase in {"preview", "script", "observation"}:
        fields = (CreationTaskExactEditRequest.model_fields if phase == "preview" else
                  CreationTaskObservationRequest.model_fields if phase == "observation" else
                  MediaScriptToolPreviewRequest.model_fields if "tool_id" in inputs else MediaScriptPreviewRequest.model_fields)
        submitted_input = {key: value for key, value in inputs.items() if key in fields}
        if phase == "script" and "tool_id" in inputs:
            submitted_input["tool_id"] = inputs["tool_id"]
    else:
        submitted_input = {key: inputs[key] for key in ("proposal_id", "base_version_id", "input_digest")}
        submitted_input["request"] = {key: value for key, value in inputs["request"].items() if key in CreationTaskEditApplyRequest.model_fields}
    if len(json.dumps(submitted_input, ensure_ascii=False).encode("utf-8")) > 64 * 1024:
        raise HTTPException(status_code=409, detail="原请求字段超过有界查询范围，不能省略字段或换绑新版重放")
    result = _read_edit_request_result(task, event_id)
    return {"request_id": str(request_id), "phase": phase, "input_digest": event.payload["input_digest"],
            "task_id": task_id, "status": "recorded" if result else "unknown",
            "submitted_input": submitted_input,
            "result_status_code": result.status_code if result else None,
            "result": json.loads(result.body) if result else None}


def _task_media_grant_or_queue(kind="waveform"):
    active = TASK_MEDIA_CONTEXT.get()
    if active is None:
        raise TaskMediaRequired(kind)
    return active[0]


# Nested public helpers bubble the media boundary to the original operation,
# preserving its accepted assistant instruction and selection.
_TASK_MEDIA_SUBMISSION = ContextVar("task_media_submission", default=False)


def _task_media_route(operation, result_kind):
    import functools
    import inspect
    def decorate(function):
        signature = inspect.signature(function)
        _TASK_MEDIA_HANDLERS[operation] = (function, signature)
        @functools.wraps(function)
        def queued(*args, **kwargs):
            bound = signature.bind(*args, **kwargs)
            bound.apply_defaults()
            request = bound.arguments["request"]
            if TASK_MEDIA_CONTEXT.get() is not None or _TASK_MEDIA_SUBMISSION.get():
                return function(*args, **kwargs)
            typed_source, edit_request_event = None, None
            if operation in {"exact_edit_preview", "media_script_preview", "media_script_tool_preview"}:
                original = bound.arguments["payload"]
                # Replays are resolved before comparing against today's version.
                if original.request_id is not None:
                    task, member_id = _exact_edit_access(bound.arguments["task_id"], request, write=True)
                    edit_request_event, fresh = _claim_edit_request(task, member_id, original.request_id,
                        "preview" if operation == "exact_edit_preview" else "script",
                        {**original.model_dump(mode="json", exclude_unset=True), **({"tool_id": bound.arguments["tool_id"]} if operation == "media_script_tool_preview" else {})})
                    if not fresh:
                        result = _read_edit_request_result(task, edit_request_event)
                        if result is not None:
                            return result
                        raise HTTPException(status_code=409, detail="原预览请求结果尚未确定，请查询原请求，不重复执行")
                try:
                    if operation in {"media_script_preview", "media_script_tool_preview"}:
                        script_payload = original
                        if operation == "media_script_tool_preview":
                            actor = _require_permit_actor(request, current_workspace_id(request))
                            try:
                                script_payload, _ref = _instantiate_script_tool(actor, bound.arguments["tool_id"], original)
                            except (KeyError, PermissionError, ScriptToolError) as exc:
                                _script_tool_error(exc)
                        typed_source = _prepare_script_request(bound.arguments["task_id"], request, script_payload)
                        if typed_source.get("reused_completed_source") is not None:
                            result = JSONResponse(status_code=200, content=typed_source["reused_completed_source"])
                            if edit_request_event:
                                _save_edit_request_result(task, edit_request_event, result)
                            return result
                    else:
                        bound.arguments["payload"], typed_source = _prepare_exact_edit_request(bound.arguments["task_id"], request, original)
                except HTTPException as exc:
                    if edit_request_event:
                        _save_edit_request_result(task, edit_request_event, JSONResponse(status_code=exc.status_code, content={"detail": exc.detail}))
                    raise
            if operation == "output_observation":
                original = bound.arguments["payload"]
                if original.request_id is not None:
                    task, member_id = _exact_edit_access(bound.arguments["task_id"], request, write=True)
                    edit_request_event, fresh = _claim_edit_request(task, member_id, original.request_id,
                        "observation", original.model_dump(mode="json", exclude_unset=True))
                    if not fresh:
                        result = _read_edit_request_result(task, edit_request_event)
                        if result is not None:
                            return result
                        raise HTTPException(status_code=409, detail="原观察请求结果尚未确定；请查原请求，不重复执行")
                try:
                    typed_source = _prepare_observation_request(bound.arguments["task_id"], request, original)
                except HTTPException as exc:
                    if edit_request_event:
                        _save_edit_request_result(task, edit_request_event, JSONResponse(status_code=exc.status_code, content={"detail": exc.detail}))
                    raise
            if operation == "command_edit_preview":
                task = _creation_task_or_404(current_workspace_id(request), bound.arguments["task_id"])
                bound.arguments["payload"] = _bind_assistant_edit_instruction(request, task, bound.arguments["payload"])
            scope = _TASK_MEDIA_SUBMISSION.set(True)
            source_token = EXACT_EDIT_SOURCE.set(typed_source)
            try:
                if operation not in {"audio_import", "recording_save"}:
                    # Pure DB proposals and external text requests finish here,
                    # without constructing a device runtime or taking a grant.
                    result = function(*bound.args, **bound.kwargs)
                    if edit_request_event:
                        _save_edit_request_result(task, edit_request_event, result)
                    return result
                raise TaskMediaRequired("upload")
            except HTTPException as exc:
                if edit_request_event:
                    _save_edit_request_result(task, edit_request_event, JSONResponse(status_code=exc.status_code, content={"detail": exc.detail}))
                raise
            except TaskMediaRequired as required:
                media_kind = required.kind
            finally:
                _TASK_MEDIA_SUBMISSION.reset(scope)
                EXACT_EDIT_SOURCE.reset(source_token)
            workspace_id = current_workspace_id(request)
            actor = _require_permit_actor(request, workspace_id)
            task_id = bound.arguments["task_id"]
            task = _creation_task_or_404(workspace_id, task_id)
            if task.owner_user_id and task.owner_user_id != (actor.user_id or actor.member_id):
                raise HTTPException(status_code=403, detail="当前成员不能安排此任务的媒体处理")
            if operation in {"audio_import", "recording_save"} and cpu_audio_budget_from_env() is None:
                raise HTTPException(status_code=503, detail="CPU 音频处理预算尚未标定，未接收媒体作业")
            values = {"_media_kind": media_kind,
                      "_draft": request.query_params.get("draft") == "true" or request.url.path.endswith("/edits/exact")}
            if typed_source is not None:
                values["_typed_source"] = typed_source
            if operation in {"media_script_preview", "media_script_tool_preview"}:
                toolchain, _budget = _script_configuration()
                values["_script_toolchain"] = {key: str(value) if isinstance(value, Path) else value for key, value in asdict(toolchain).items()}
                if operation == "media_script_tool_preview":
                    _expanded, values["_recipe_ref"] = _instantiate_script_tool(actor, bound.arguments["tool_id"], bound.arguments["payload"])
            created_input = None
            try:
                for name, value in bound.arguments.items():
                    if name in {"request", "task_id"}:
                        continue
                    if isinstance(value, BaseModel):
                        values[name] = value.model_dump(mode="json", exclude_unset=True)
                        if "base_version_id" in values[name] and values[name]["base_version_id"] is None:
                            values[name]["base_version_id"] = task.current_timeline_version_id
                    elif isinstance(value, UploadFile) or hasattr(value, "file") and hasattr(value, "filename"):
                        suffix = Path(value.filename or "").suffix.lower()
                        allowed = {".wav", ".mp3", ".m4a", ".aac", ".flac"} if operation == "audio_import" else {".webm", ".mp4", ".m4a", ".ogg", ".wav"}
                        if suffix not in allowed:
                            raise HTTPException(status_code=422, detail="当前上传音频格式不可用")
                        root = settings.effective_temporary_root_path / "task-media-inputs" / media_digest([workspace_id, actor.identity_payload()])
                        root.mkdir(parents=True, exist_ok=True)
                        partial = root / (uuid4().hex + ".part")
                        limit = (512 if operation == "audio_import" else 50) * 1024 * 1024
                        total, digest = 0, hashlib.sha256()
                        try:
                            with partial.open("xb") as target:
                                while chunk := value.file.read(1024 * 1024):
                                    total += len(chunk)
                                    if total > limit:
                                        raise HTTPException(status_code=422, detail="上传音频超过本次大小上限")
                                    target.write(chunk)
                                    digest.update(chunk)
                            if total == 0:
                                raise HTTPException(status_code=422, detail="上传音频为空")
                            staged = root / (digest.hexdigest() + suffix)
                            if staged.is_symlink():
                                raise HTTPException(status_code=422, detail="音频暂存位置不可用")
                            try:
                                os.link(partial, staged)
                            except FileExistsError:
                                if staged.stat().st_size != total:
                                    raise HTTPException(status_code=409, detail="已保存的固定音频输入发生变化，请检查本机存储")
                            else:
                                created_input = staged
                        finally:
                            partial.unlink(missing_ok=True)
                        values[name] = {"staged_input": str(staged.relative_to(settings.effective_temporary_root_path)),
                            "filename": Path(value.filename).name, "size_bytes": total, "sha256": digest.hexdigest()}
                    else:
                        values[name] = value
                runtime = _creation_runtime()
                media = runtime.registrations["creation_job"].owner.task_media
                if operation in {"audio_edit_preview", "visual_edit_preview", "exact_edit_preview", "command_edit_preview", "compound_selection_preview"} and task.montage_plan_id and task.current_timeline_version_id is None:
                    media.facts(workspace_id, task_id, operation, values, actor)
                    if media.verify_identity(actor) != "ready":
                        raise PermissionError("媒体处理身份失效或无法复核")
                    montage = creation_task_montage_plan_from_payload(production_repo.get_creation_task_montage_plan(workspace_id, task_id))
                    base = _ensure_montage_base_version(workspace_id, task, montage)
                    if "base_version_id" in values.get("payload", {}):
                        values["payload"]["base_version_id"] = base.id
                job = media.submit(runtime, actor, task_id, operation, values, result_kind)
                receipt = _task_media_job_response(media, job, actor, runtime)
                if edit_request_event:
                    _save_edit_request_result(task, edit_request_event, JSONResponse(status_code=202, content=receipt))
                receipt["result"] = None
                return JSONResponse(status_code=202, content=receipt)
            except Exception as exc:
                if created_input is not None:
                    relative = str(created_input.relative_to(settings.effective_temporary_root_path))
                    with production_repo._connect() as conn:
                        referenced = conn.execute("SELECT 1 FROM task_events WHERE workspace_id=? AND event_type='task_media_submitted' "
                            "AND json_extract(payload_json,'$.arguments.audio.staged_input')=? LIMIT 1", (workspace_id,relative)).fetchone()
                    if referenced is None:
                        created_input.unlink(missing_ok=True)
                if isinstance(exc, PermissionError):
                    raise HTTPException(status_code=403, detail=str(exc)) from exc
                if isinstance(exc, (ValueError, KeyError)):
                    raise HTTPException(status_code=422, detail=str(exc)) from exc
                raise
        return queued
    return decorate


def _task_media_facts(workspace_id, task_id, operation, arguments, actor):
    from app.canvas import canvas_size
    from app.member_permits import cpu_render_budget_from_env
    task = production_repo.get_creation_task(workspace_id, task_id)
    source = arguments.get("_typed_source")
    if source is not None:
        version = production_repo.get_timeline_version(workspace_id, task.current_timeline_version_id) if task.current_timeline_version_id else None
        if (source["workspace_id"], source["task_id"], source["member_id"], source["expected_timeline_version_id"], source["expected_timeline_sequence"]) != (
                workspace_id, task_id, actor.user_id or actor.member_id, task.current_timeline_version_id, version.sequence if version else 0):
            raise ValueError("封存的类型化编辑输入或成员已失效")
    if operation == "output_observation":
        return _output_observation_facts(workspace_id, task_id, arguments, actor)
    if operation in {"media_script_preview", "media_script_tool_preview"}:
        if operation == "media_script_tool_preview":
            invocation = MediaScriptToolPreviewRequest.model_validate(arguments["payload"])
            payload, recipe_ref = _instantiate_script_tool(actor, arguments["tool_id"], invocation)
            if recipe_ref != arguments["_recipe_ref"]:
                raise ValueError("封存配方版本或来源发生变化")
        else:
            payload = MediaScriptPreviewRequest.model_validate(arguments["payload"])
        version = production_repo.get_timeline_version(workspace_id, task.current_timeline_version_id) if task.current_timeline_version_id else None
        if (payload.expected_timeline_version_id, payload.expected_timeline_sequence) != (task.current_timeline_version_id, version.sequence if version else 0):
            raise ValueError("脚本输入时间线已变化")
        toolchain, budget = _script_configuration()
        frozen = arguments.get("_script_toolchain")
        descriptor = {key: str(value) if isinstance(value, Path) else value for key, value in asdict(toolchain).items()}
        if frozen != descriptor:
            raise ValueError("脚本受校准工具链描述已变化")
        sealed, _paths, files = seal_script(production_repo, artifact_store, task, payload, toolchain)
        resources = media_script_resource_facts(sealed=sealed, limits=script_limits(budget),
            input_sizes={item["name"]: item["size_bytes"] for item in files}, threads=budget.max_threads)
        resources["definition_bytes"] = len(script_definition(sealed, payload))
        if resources["definition_bytes"] > budget.additional_disk_bytes:
            raise ValueError("成功程序元数据超过本次磁盘预留，不安排脚本")
        return {"base_version_id": task.current_timeline_version_id, "timeline_sequence": version.sequence if version else 0,
                "script_digest": sealed.digest, "toolchain": descriptor, "files": files}, resources
    plan_payload = production_repo.get_creation_task_montage_plan(workspace_id, task_id) if task.montage_plan_id else None
    plan = creation_task_montage_plan_from_payload(plan_payload) if plan_payload else None
    # Bind the whole current task input, excluding renderer progress fields.
    transient = {"status", "message", "output_path", "subtitle_path", "updated_at"}
    snapshot = {key: value for key, value in creation_task_montage_plan_to_payload(plan).items()
                if key not in transient} if plan else None
    payload = arguments.get("payload", {})
    picture_candidates = [plan] if plan is not None else []
    if operation == "exact_edit_preview" and payload.get("operation_type") == "EditGraphicOverlay":
        overlay_payload = CreationTaskExactEditRequest.model_validate(payload)
        picture_candidates.append(_graphic_overlay_candidate(plan, overlay_payload))
    expected = payload.get("base_version_id")
    if "base_version_id" in payload and expected != task.current_timeline_version_id:
        raise ValueError("时间线已变化，请重新安排当前要求")
    if arguments.get("_media_kind") == "clip_preview":
        from app.canvas import preview_size
        if plan is None:
            raise ValueError("当前任务没有可预览的镜头")
        selected = payload.get("clip_id") or next((ref[5:] for ref in payload.get("selected_object_refs", []) if ref.startswith("clip:")), None)
        clip = next((item for item in plan.clips if item.id == selected), None)
        if clip is None:
            raise ValueError("当前选中镜头不存在")
        if clip.person_render_id:
            from app.creation_execution import presenter_inputs, current_presenter_render
            creation_plan = production_repo.get_creation_plan(workspace_id,task.plan_id)
            script = production_repo.get_creation_task_script(workspace_id,task.confirmed_script_id)
            matches = [current_presenter_render(production_repo,task,segment,person_request,_person_render_media_path)
                       for segment,person_request in presenter_inputs(production_repo,task,script,creation_plan,_presenter_model_ids())]
            if not any(item is not None and item.id==clip.person_render_id for item in matches):
                raise PermissionError("当前人物/声音授权或片段版本已失效")
            source = _person_render_media_path(production_repo.get_person_render(workspace_id,task_id,clip.person_render_id))
            _, budget = presenter_budgets_from_env()
            kind = "creation_presenter_render"
        else:
            asset = production_repo.get_asset(workspace_id,clip.asset_id)
            if not material_allows_footage(asset) or not content_readable(user_id=actor.user_id or actor.member_id,
                    local_diagnostic=False,visibility=asset.visibility,owner_user_id=asset.owner_user_id):
                raise PermissionError("当前成员或素材使用状态不允许预览此镜头")
            source = production_repo.resolve_clip_media_reference(workspace_id,clip.asset_id,clip.source_path)
            budget = cpu_render_budget_from_env()
            kind = "creation_render"
        if source is None or budget is None:
            raise ValueError("镜头媒体或 CPU 预览预算不可用")
        stat = source.stat()
        width,height = preview_size(plan.aspect_ratio)
        # The bounded window is independent of the parent movie's duration.
        window = min(5., clip.timeline_end_seconds-clip.timeline_start_seconds)
        if payload.get("operation_type") == "ChangeClipSpeed":
            window = 5.
        resources = {"kind":kind,"execution_mode":"cpu_ffmpeg","duration_seconds":window,
            "width_px":width,"height_px":height,"input_bytes":stat.st_size,"clip_count":1,"overlay_count":0,
            "max_output_bytes":budget.max_output_bytes,"threads":budget.max_threads,"timeout_seconds":budget.max_timeout_seconds,
            "clip_preview":True,"silent":True,"preview_window_limit_seconds":5.}
        facts = {"base_version_id":task.current_timeline_version_id,"clip":asdict(clip),"aspect_ratio":plan.aspect_ratio,
            "source":[clip.source_path,stat.st_size,stat.st_mtime_ns,stat.st_ctime_ns]}
        return facts,resources
    audio_operations = {"audio_import", "recording_save", "audio_listen", "audio_extract", "audio_edit_preview", "audio_waveform", "narration_waveform"}
    if operation == "command_edit_preview" and arguments.get("_media_kind") in {"audio_mix", "audio_probe", "audio_stretch"} and not re.fullmatch(r"(?:剪掉|删掉|删除)(?:当前镜头(?:的)?)?(?:停顿|静音)[。！]?", payload.get("raw_command", "").strip()):
        audio_operations.add(operation)
    files, audio_inputs, audio_uses, graphics = [], [], {}, []
    service = _task_audio()
    def remember(reference, path, *, audio=False, metadata=None):
        stat = path.stat()
        fact = [reference, stat.st_size, stat.st_mtime_ns, stat.st_ctime_ns]
        if fact not in files:
            files.append(fact)
        if audio and not any(item["reference"] == reference for item in audio_inputs):
            values = metadata if metadata is not None else service.source_metadata(workspace_id, task_id, reference)
            audio_inputs.append({"reference": reference, "path": str(path.resolve()), "size_bytes": stat.st_size,
                                 "uses": audio_uses.get(reference, 1), **values})
    if plan is not None and operation not in {"audio_import", "recording_save", "narration_waveform"}:
        if operation not in audio_operations:
            _validate_montage_material_use(workspace_id, plan)
            person_ids = set()
            if any(clip.person_render_id for clip in plan.clips):
                from app.creation_execution import presenter_inputs, current_presenter_render
                creation_plan = production_repo.get_creation_plan(workspace_id, task.plan_id)
                script = production_repo.get_creation_task_script(workspace_id, task.confirmed_script_id)
                for segment, person_request in presenter_inputs(production_repo, task, script, creation_plan, _presenter_model_ids()):
                    current = current_presenter_render(production_repo, task, segment, person_request, _person_render_media_path)
                    if current is not None:
                        person_ids.add(current.id)
            for clip in plan.clips:
                if clip.person_render_id:
                    if clip.person_render_id not in person_ids:
                        raise PermissionError("当前人物/声音授权或片段版本已失效")
                else:
                    asset = production_repo.get_asset(workspace_id, clip.asset_id)
                    if not content_readable(user_id=actor.user_id or actor.member_id, local_diagnostic=False,
                        visibility=asset.visibility, owner_user_id=asset.owner_user_id):
                        raise PermissionError("当前成员不能读取镜头素材")
                path = (_person_render_media_path(production_repo.get_person_render(workspace_id, task_id, clip.person_render_id))
                        if clip.person_render_id else production_repo.resolve_clip_media_reference(workspace_id, clip.asset_id, clip.source_path))
                if path is None:
                    raise ValueError("当前人物片段没有有效媒体")
                remember(clip.source_path, path)
            for reference in dict.fromkeys(item["source_ref"] for candidate in picture_candidates
                    for item in candidate.graphic_overlays if item.get("kind") == "image"):
                item = graphic_source_facts(production_repo, artifact_store, workspace_id, task_id, reference, actor=actor)
                graphics.append(item)
                remember(reference, Path(item["path"]))
        graph = _effective_audio_timeline(plan)
        solo = set(payload.get("solo_track_ids", []))
        clips = [clip for track in graph.tracks if not track.muted and (not solo or track.id in solo)
                 for clip in track.clips if not clip.muted]
        if operation == "audio_waveform":
            clips = [clip for track in graph.tracks for clip in track.clips if clip.id == arguments["clip_id"]]
            if not clips:
                raise ValueError("所选音频片段不存在")
        if arguments.get("_media_kind") == "audio_stretch":
            selected = set(payload.get("selected_object_refs", []))
            for video_clip in plan.clips:
                if f"clip:{video_clip.id}" in selected:
                    reference = production_repo.workspace_media_reference_for_asset(workspace_id, video_clip.asset_id)
                    remember(reference, production_repo.resolve_clip_media_reference(workspace_id, video_clip.asset_id, video_clip.source_path),
                        audio=True, metadata=service.source_metadata(workspace_id, task_id, reference))
        references = {clip.source_ref for clip in clips}
        audio_uses.update(Counter(clip.source_ref for clip in clips))
        if operation == "audio_edit_preview":
            edit = AudioEditRequest.model_validate(payload)
            duration_ms = round(plan.duration_seconds * 1000)
            if edit.action == "replace_narration":
                edit = edit.model_copy(update={"values": {**edit.values, "source_end_ms": duration_ms}})
            candidate = apply_audio_edit(graph, edit, duration_ms)
            after_clips = [clip for track in candidate.tracks if not track.muted for clip in track.clips if not clip.muted]
            references.update(clip.source_ref for clip in after_clips)
            for reference, count in Counter(clip.source_ref for clip in after_clips).items():
                audio_uses[reference] = max(audio_uses.get(reference, 0), count)
        for reference in sorted(references):
            remember(reference, service.source(workspace_id, task_id, reference, actor=actor), audio=True)
    if "audio" in arguments:
        relative = arguments["audio"]["staged_input"]
        path = settings.effective_temporary_root_path / relative
        if path.is_symlink() or not path.resolve().is_relative_to(settings.effective_temporary_root_path.resolve()):
            raise ValueError("音频暂存输入越界")
        remember(relative, path, audio=True, metadata={"duration_seconds": None, "sample_rate": None, "channels": None})
    if operation == "narration_waveform":
        if not task.narration_cache_key:
            raise ValueError("当前任务没有可读取的配音")
        reference = production_repo.narration_artifact_reference(task.narration_cache_key)
        remember(reference, service.source(workspace_id, task_id, reference, actor=actor), audio=True)
    facts = {"base_version_id": task.current_timeline_version_id, "script_id": task.confirmed_script_id,
             "script_digest": production_repo.confirmed_creation_task_script_digest(workspace_id, task_id, task.confirmed_script_id)
                 if task.confirmed_script_id else None,
             "plan_id": task.plan_id, "plan_digest": media_digest(asdict(production_repo.get_creation_plan(workspace_id, task.plan_id))), "montage": snapshot, "files": files,
             "narration_cache_key": task.narration_cache_key}
    if operation == "audio_import":
        facts = {"base_version_id": None, "files": files}
    if graphics:
        facts["graphic_sources"] = graphics
    if operation in audio_operations:
        budget = cpu_audio_budget_from_env()
        if budget is None:
            raise ValueError("CPU 音频处理预算尚未标定，未启动媒体")
        if not audio_inputs and operation != "audio_listen":
            raise ValueError("没有固定的音频输入，未启动媒体")
        for source in audio_inputs:
            for field, cap in (("duration_seconds", budget.max_source_duration_seconds),
                               ("sample_rate", budget.max_sample_rate), ("channels", budget.max_channels)):
                value = source[field]
                if value is not None and (not isinstance(value, (int, float)) or value <= 0 or value > cap):
                    raise ValueError("已保存的音频源规格超出标定预算")
        known_duration = max((item["duration_seconds"] or 0 for item in audio_inputs), default=0)
        if operation in {"audio_import", "recording_save"}:
            output_duration = budget.max_output_duration_seconds
        elif operation in {"audio_waveform", "narration_waveform"}:
            if known_duration > budget.max_output_duration_seconds:
                raise ValueError("当前音频超过波形输出时长预算")
            output_duration = budget.max_output_duration_seconds
        else:
            if plan is None:
                raise ValueError("当前任务没有可试听的音轨")
            start = payload.get("start_seconds", 0)
            end = payload.get("end_seconds", plan.duration_seconds)
            if not 0 <= start < end <= plan.duration_seconds:
                raise ValueError("试听范围必须位于时间线内")
            output_duration = end - start
        # Limits are explicit upper bounds, never reported as measurements.
        resources = {"kind": "task_audio", "execution_mode": "cpu_ffmpeg",
            "input_policy": "probe_then_bounded_decode", "inputs": audio_inputs,
            "input_count": sum(item["uses"] for item in audio_inputs),
            "input_bytes": sum(item["size_bytes"] * item["uses"] for item in audio_inputs),
            "source_duration_limit_seconds": budget.max_source_duration_seconds,
            "output_duration_limit_seconds": output_duration,
            "source_sample_rate_limit": budget.max_sample_rate, "source_channels_limit": budget.max_channels,
            "output_sample_rate_limit": 8000 if operation in {"audio_waveform", "narration_waveform"} else
                budget.max_sample_rate if operation in {"audio_import", "recording_save"} else 48000,
            "output_channels_limit": budget.max_channels if operation in {"audio_import", "recording_save", "audio_waveform", "narration_waveform"} else 2,
            "max_output_bytes": budget.max_output_bytes, "threads": budget.max_threads,
            "timeout_seconds": budget.max_timeout_seconds}
        if (resources["input_count"] > budget.max_input_count or resources["input_bytes"] > budget.max_input_bytes
                or output_duration > budget.max_output_duration_seconds
                or resources["output_sample_rate_limit"] > budget.max_sample_rate):
            raise ValueError("当前音频处理输入或输出超出标定预算")
    else:
        if plan is None:
            raise ValueError("当前任务没有可预览的故事板")
        budget = cpu_render_budget_from_env()
        if budget is None:
            raise ValueError("CPU 画面预览预算尚未标定，未启动媒体")
        if any(clip.person_render_id for clip in plan.clips):
            _, person_budget = presenter_budgets_from_env()
            if person_budget is None:
                raise ValueError("人物组合 CPU 预览预算尚未标定，未启动媒体")
            budget = person_budget
        width, height = canvas_size(plan.aspect_ratio)
        changed_width, changed_height = canvas_size(payload.get("aspect_ratio") or plan.aspect_ratio)
        width, height = max(width, changed_width), max(height, changed_height)
        resources = {"kind": "creation_presenter_render" if any(clip.person_render_id for clip in plan.clips) else "creation_render", "execution_mode": "cpu_ffmpeg", "duration_seconds": plan.duration_seconds,
            "width_px": width, "height_px": height, "input_bytes": sum(item[1] for item in files),
            "clip_count": len(plan.clips), "overlay_count": max(len(candidate.graphic_overlays) for candidate in picture_candidates),
            "threads": budget.max_threads, "timeout_seconds": budget.max_timeout_seconds,
            "max_output_bytes": budget.max_output_bytes}
        # Local recognition has model memory requirements beyond FFmpeg budgets.
        if "校准" in payload.get("raw_command", ""):
            raise ValueError("本地字幕识别尚无独立标定的模型资源许可，未启动识别")
    return facts, resources


def _execute_task_media_operation(job, event, actor):
    from types import SimpleNamespace
    import typing
    function, signature = _TASK_MEDIA_HANDLERS[event["operation"]]
    hints = typing.get_type_hints(function)
    path = "/api/creation-tasks/" + job.task_id + "/media-execution"
    request = Request({"type": "http", "method": "POST", "path": path,
        "query_string": b"draft=true" if event["arguments"].get("_draft") else b"", "headers": [],
        "state": {"principal": SimpleNamespace(workspace_id=job.workspace_id, user_id=actor.user_id or actor.member_id)}})
    values = {"task_id": job.task_id, "request": request}
    for name, value in event["arguments"].items():
        if name.startswith("_"):
            continue
        if name == "audio":
            # Uploads have already been staged; the typed upload handler reads only this fixed reference.
            values[name] = SimpleNamespace(filename=value["filename"], staged_input=value["staged_input"], source_sha256=value["sha256"])
        elif isinstance(hints.get(name), type) and issubclass(hints[name], BaseModel):
            values[name] = hints[name].model_validate(value)
            if name == "payload" and getattr(values[name], "assistant_turn_id", None) is not None:
                values[name] = hints[name].model_validate(values[name].model_dump(
                    mode="json", exclude_unset=True, exclude={"assistant_turn_id"}))
        else:
            values[name] = value
    source = event["arguments"].get("_typed_source")
    if source is not None:
        source = {**source, "media_job_id": job.id, "actor_identity": actor.identity_payload()}
    source_token = EXACT_EDIT_SOURCE.set(source)
    try:
        result = function(**values)
    finally:
        EXACT_EDIT_SOURCE.reset(source_token)
    if isinstance(result, BaseModel):
        return result.model_dump(mode="json")
    if isinstance(result, JSONResponse):
        return json.loads(result.body)
    return result


def _validate_task_media_result(job, event, result, context):
    if event["operation"] == "output_observation":
        context.check()
        if (result.get("timeline_version_id"), result.get("output", {}).get("sha256")) != (
                event["input_facts"]["base_version_id"], event["input_facts"]["output"]["sha256"]):
            raise ValueError("观察结果未绑定原实际输出版本和摘要")
        if len(json.dumps(result, ensure_ascii=False).encode("utf-8")) > MAX_OBSERVATION_BYTES:
            raise ValueError("观察回执超过有界大小")
        return []
    outputs = []
    for record in production_repo.list_artifact_records(job.workspace_id, job.task_id):
        if record.producer_job_id != job.id:
            continue
        context.check()
        publication = artifact_store.describe(record.logical_ref)
        if (publication.sha256, publication.size_bytes) != (record.sha256, record.size_bytes):
            raise ValueError("已提交预览产物内容发生变化")
        path = artifact_store.resolve_file(record.logical_ref)
        stat = path.stat()
        outputs.append({"reference":record.logical_ref,"size_bytes":stat.st_size,
                        "mtime_ns":stat.st_mtime_ns,"ctime_ns":stat.st_ctime_ns})
        if event["operation"] in {"media_script_preview", "media_script_tool_preview"}:
            if record.kind == "media_script_definition":
                if stat.st_size != event["resources"]["definition_bytes"]:
                    raise ValueError("成功程序定义大小与封存事实不一致")
                definition = json.loads(path.read_bytes())
                if definition["script_digest"] != event["input_facts"]["script_digest"]:
                    raise ValueError("成功程序定义摘要不属于原作业")
                continue
            from PIL import Image
            if record.kind != "graphic_source" or path.suffix != ".png":
                raise ValueError("脚本产物不是登记PNG来源")
            with Image.open(path) as image:
                image.load()
                if image.format != "PNG" or (image.width, image.height) != (result["width"], result["height"]):
                    raise ValueError("脚本PNG实测与发布结果不一致")
            continue
        if path.suffix == ".mp4":
            from app.montage import probe_preview_video
            with production_repo._connect() as conn:
                row = conn.execute("SELECT payload_json FROM task_events WHERE workspace_id=? AND job_id=? AND event_type='task_media_input' "
                    "AND id=?", (job.workspace_id,job.id,f"event_{job.id}_{record.id.removeprefix('artifact_')}_input")).fetchone()
            inputs = json.loads(row["payload_json"])["media_input"]
            if "clip" in inputs:
                from app.canvas import preview_size
                clip = inputs["clip"]
                size = preview_size(inputs["aspect_ratio"])
                duration = min(5,clip["timeline_end_seconds"]-clip["timeline_start_seconds"])
                silent = True
            else:
                size = canvas_size(inputs["plan"]["aspect_ratio"])
                duration = inputs["plan"]["duration_seconds"]
                silent = False
            probe_preview_video(path,context,expected_size=size,expected_duration_seconds=duration,silent=silent)
        else:
            probe_audio_source(path, scheduler=context.scheduler, grant=context.grant,
                cancel_event=context.cancel_event, deadline_monotonic=context.deadline_monotonic, output=True)
    context.check()
    return outputs


def _task_media_outputs_current(job):
    records = [item for item in production_repo.list_artifact_records(job.workspace_id,job.task_id) if item.producer_job_id==job.id]
    if not records:
        return True
    try:
        verified = production_repo.get_task_event(job.workspace_id,f"event_{job.id}_verified").payload["outputs"]
        if not verified or {item["reference"] for item in verified} != {item.logical_ref for item in records}:
            return False
        for item in verified:
            stat = artifact_store.resolve_file(item["reference"]).stat()
            if (stat.st_size,stat.st_mtime_ns,stat.st_ctime_ns) != (item["size_bytes"],item["mtime_ns"],item["ctime_ns"]):
                return False
    except (KeyError,FileNotFoundError,OSError):
        return False
    return True


def _task_media_job_response(media, job, actor, runtime):
    from app.schemas import TaskMediaJobResponse
    current, event = media.read(job.workspace_id, job.id)
    if CreationExecutionActor.from_event(job.workspace_id, event) != actor or media.verify_identity(actor) != "ready":
        raise HTTPException(status_code=404, detail="任务媒体作业不存在")
    verdict = media.check(current, event, actor)
    status = "stale" if verdict != "ready" and current.status not in {"failed", "cancelled"} else current.status
    result = None
    result_invalid = status == "succeeded" and not _task_media_outputs_current(current)
    if result_invalid:
        status = "failed"
    if status == "succeeded":
        result = production_repo.get_task_event(job.workspace_id, f"event_{job.id}_result").payload["result"]
    device_request_id = waiting_reason = None
    with production_repo._connect() as conn:
        row = conn.execute("SELECT id FROM device_work_requests WHERE workspace_id=? AND owner_type='creation_job' AND owner_id=? ORDER BY created_at DESC LIMIT 1",
                           (job.workspace_id, job.id)).fetchone()
    if row:
        view = runtime.scheduler.view_for(row["id"], actor)
        device_request_id = view.get("id", view.get("request_id"))
        waiting_reason = view.get("wait_reason")
    payload = event["arguments"].get("payload", {})
    refs = payload.get("selected_object_refs", [])
    if not refs and payload.get("clip_ids"):
        refs = [f"clip:{item}" for item in payload["clip_ids"]]
    if not refs and payload.get("clip_id"):
        refs = [f"clip:{payload['clip_id']}"]
    if not refs and payload.get("target_id"):
        refs = [f"audio:{payload['target_id']}"]
    if not refs and payload.get("track_id"):
        refs = [f"subtitle-track:{payload['track_id']}"]
    if not refs and event["operation"] == "audio_waveform":
        refs = [f"audio:{event['arguments']['clip_id']}"]
    refs = [item for item in refs if re.fullmatch(r"(?:clip|audio|cue|overlay|subtitle-track):[A-Za-z0-9_-]{1,120}", item)][:8]
    return TaskMediaJobResponse(job_id=job.id, status=status, result_kind=event["result_kind"],
        operation=event["operation"], target_refs=refs, input_digest=job.input_digest, created_at=job.created_at,
        result_url=f"/api/creation-tasks/{job.task_id}/media-jobs/{job.id}", base_version_id=event["input_facts"]["base_version_id"],
        device_request_id=device_request_id, waiting_reason=waiting_reason, result=result,
        failure_reason="result_invalid" if result_invalid else current.failure_reason,
        repair_action="本次媒体文件已丢失或变化；请恢复原文件。系统不会重渲染已提交产物。" if result_invalid else current.repair_action).model_dump(mode="json")


def _observation_version(task, payload):
    version = production_repo.get_timeline_version(task.workspace_id, task.current_timeline_version_id) if task.current_timeline_version_id else None
    if (payload.expected_timeline_version_id, payload.expected_timeline_sequence) != (
            task.current_timeline_version_id, version.sequence if version else 0):
        raise ValueError("观察目标时间线已变化，请回读当前版本")
    return version


def _prepare_observation_request(task_id, request, payload):
    task, member_id = _exact_edit_access(task_id, request, write=True)
    try:
        version = _observation_version(task, payload)
    except ValueError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    actor = _require_permit_actor(request, task.workspace_id)
    source = {"workspace_id": task.workspace_id, "task_id": task_id, "member_id": member_id,
        "expected_timeline_version_id": task.current_timeline_version_id,
        "expected_timeline_sequence": version.sequence if version else 0,
        "actor_identity": actor.identity_payload(), "request_id": str(payload.request_id) if payload.request_id else None}
    if payload.assistant_turn_id is not None:
        try:
            origin = conversation_repo.task_turn_source(str(payload.assistant_turn_id), task.workspace_id, member_id, task_id)
        except ValueError as exc:
            raise HTTPException(status_code=409, detail=str(exc)) from exc
        snapshot = origin["context"].get("target_snapshot", {})
        if (snapshot.get("timeline_version_id"), snapshot.get("timeline_sequence")) != (
                task.current_timeline_version_id, version.sequence if version else 0):
            raise HTTPException(status_code=409, detail="观察请求的助手轮次版本已失效")
        source.update(assistant_turn_id=str(payload.assistant_turn_id), conversation_id=origin["conversation_id"],
                      raw_command=origin["raw_command"])
    return source


def _registered_observation_output(workspace_id, task_id, target, actor):
    task = production_repo.get_creation_task(workspace_id, task_id)
    if target.kind == "final":
        _task, plan, path, _digest = _quality_check_source(workspace_id, task_id)
        record = next(item for item in production_repo.list_artifact_records(workspace_id, task_id)
                      if item.logical_ref == plan.output_path and item.kind == "rendered_video")
        binding = {"kind": "composed_output", "montage": creation_task_montage_plan_to_payload(plan)}
        width, height = canvas_size(plan.aspect_ratio)
    else:
        job = production_repo.get_job_run(workspace_id, target.job_id)
        if job.task_id != task_id or job.kind != TASK_MEDIA_KIND or job.status != "succeeded":
            raise ValueError("只能观察本任务真实成功的媒体作业输出")
        start = production_repo.get_task_event(workspace_id, f"event_{job.id}_start").payload
        if (CreationExecutionActor.from_event(workspace_id, start) != actor
                or start["input_facts"]["base_version_id"] != task.current_timeline_version_id):
            raise PermissionError("原媒体作业身份或输入版本不再适用当前目标")
        record = production_repo.get_artifact_record(workspace_id, target.artifact_id)
        if record.task_id != task_id or record.producer_job_id != job.id:
            raise ValueError("产物不属于指定任务媒体作业")
        path = artifact_store.resolve_file(record.logical_ref)
        if path.suffix == ".png" and record.kind == "graphic_source":
            graphic = graphic_source_facts(production_repo, artifact_store, workspace_id, task_id, record.logical_ref, actor=actor)
            width, height = graphic["width"], graphic["height"]
            binding = {"kind": "graphic_source", "applied": False}
        elif path.suffix == ".mp4":
            _task_audio().validate_source_access(workspace_id, task_id, record.logical_ref, actor)
            _task_audio().validate_material_use(workspace_id, task_id, record.logical_ref)
            saved = production_repo.get_task_event(workspace_id,
                f"event_{job.id}_{record.id.removeprefix('artifact_')}_input").payload
            binding = {"kind": "composed_preview", "media_input": saved["media_input"]}
            if "clip" in saved["media_input"]:
                from app.canvas import preview_size
                width, height = preview_size(saved["media_input"]["aspect_ratio"])
            else:
                width, height = canvas_size(saved["media_input"]["plan"]["aspect_ratio"])
        else:
            raise ValueError("本轮只能观察登记 MP4 预览或 PNG 图片来源")
        if not _task_media_outputs_current(job):
            raise ValueError("原媒体输出已丢失或变化，不能观察旧成功状态")
    publication = artifact_store.describe(record.logical_ref)
    if (publication.sha256, publication.size_bytes) != (record.sha256, record.size_bytes):
        raise ValueError("观察媒体与真实登记摘要不一致")
    stat = path.stat()
    output = {"artifact_id": record.id, "artifact_kind": record.kind, "sha256": record.sha256,
              "registered_width": width, "registered_height": height,
              "size_bytes": record.size_bytes, "producer_job_id": record.producer_job_id,
              "logical_ref": record.logical_ref, "mtime_ns": stat.st_mtime_ns, "ctime_ns": stat.st_ctime_ns}
    return path, output, binding


def _output_observation_facts(workspace_id, task_id, arguments, actor):
    payload = CreationTaskObservationRequest.model_validate(arguments["payload"])
    task = production_repo.get_creation_task(workspace_id, task_id)
    version = _observation_version(task, payload)
    path, output, binding = _registered_observation_output(workspace_id, task_id, payload.target, actor)
    budget = cpu_render_budget_from_env()
    if budget is None:
        raise ValueError("实际画面观察的 CPU 执行预算尚未标定")
    facts = {"base_version_id": task.current_timeline_version_id, "timeline_sequence": version.sequence if version else 0,
             "output": output, "binding": binding, "target": payload.target.model_dump(mode="json"),
             "sample_times_seconds": payload.sample_times_seconds}
    width, height = output["registered_width"], output["registered_height"]
    scale = min(1., MAX_SAMPLE_EDGE / width, MAX_SAMPLE_EDGE / height)
    sample_width, sample_height = max(1, round(width * scale)), max(1, round(height * scale))
    sample_count = 1 if path.suffix == ".png" else len(payload.sample_times_seconds) or 3
    observation_budget = observation_budget_from_env()
    ocr_worker = Path(settings.native_ocr_worker_path).expanduser() if settings.native_ocr_worker_path else None
    if observation_budget is not None and ocr_worker is not None and ocr_worker.is_file():
        worker_digest = hashlib.sha256(ocr_worker.read_bytes()).hexdigest()
        if worker_digest == observation_budget.worker_sha256:
            facts["ocr"] = {"worker_sha256": worker_digest, "status": "ready"}
            resources = {"kind": "task_output_observation", "execution_mode": "local_ffmpeg_apple_vision",
                "worker_sha256": worker_digest, "sample_count": sample_count,
                "source_pixels": output["registered_width"] * output["registered_height"],
                "width_px": sample_width, "height_px": sample_height, "input_bytes": path.stat().st_size,
                "threads": observation_budget.max_threads, "timeout_seconds": observation_budget.max_timeout_seconds,
                "max_output_bytes": observation_budget.max_output_bytes}
            return facts, resources
        facts["ocr"] = {"status": "unavailable", "reason": "本地 OCR worker 摘要与已标定执行文件不一致。"}
    else:
        facts["ocr"] = {"status": "unavailable", "reason": "本地 OCR 未配置或输出观察执行范围尚未标定。"}
    resources = {"kind": "creation_render", "execution_mode": "cpu_ffmpeg",
        "duration_seconds": float(sample_count),
        "width_px": sample_width, "height_px": sample_height, "input_bytes": path.stat().st_size,
        "clip_count": 1, "overlay_count": 0, "threads": 1,
        "timeout_seconds": budget.max_timeout_seconds, "max_output_bytes": budget.max_output_bytes}
    if width * height > budget.max_width_px * budget.max_height_px:
        raise ValueError("实际输出源帧像素超过已标定 CPU 范围")
    return facts, resources


def _bounded_quality_evidence(record):
    evidence = record["evidence"]
    findings = evidence.get("findings", [])
    return {"check_id": record["check_id"], "timeline_version_id": record["timeline_version_id"],
        "render_ref": record["render_ref"], "check_state": record["check_state"],
        "result_status": record["result_status"], "checked_at": record["checked_at"],
        "error": record["error"], "validation_scope": "deterministic_media_errors_only",
        "findings": findings[:20], "findings_total": len(findings),
        "findings_truncated": len(findings) > 20, "unavailable": evidence.get("unavailable", [])}


def _task_observation_facts(task_id, request):
    workspace_id = current_workspace_id(request)
    task = _quality_check_task_access(request, workspace_id, task_id)
    current = _creation_task_quality_check_response(workspace_id, task_id).model_dump(mode="json")
    findings = current["findings"]
    current["findings_total"], current["findings_truncated"] = len(findings), len(findings) > 20
    current["findings"] = findings[:20]
    current.pop("clipping_summary", None)
    with production_repo._connect() as conn:
        rows = conn.execute("""SELECT j.id, e.payload_json FROM job_runs j JOIN task_events e
            ON e.workspace_id=j.workspace_id AND e.id='event_' || j.id || '_start'
            WHERE j.workspace_id=? AND j.task_id=? AND j.kind=?
            AND json_extract(e.payload_json,'$.operation')='output_observation'
            AND json_extract(e.payload_json,'$.member_id')=?
            ORDER BY j.created_at DESC,j.id DESC LIMIT 5""",
            (workspace_id, task_id, TASK_MEDIA_KIND, _assistant_member_id(request, workspace_id))).fetchall()
    observations = []
    for row in rows:
        job = production_repo.get_job_run(workspace_id, row["id"])
        start = json.loads(row["payload_json"])
        result = None
        if job.status == "succeeded":
            result = production_repo.get_task_event(workspace_id, f"event_{job.id}_result").payload["result"]
        stale = start["input_facts"]["base_version_id"] != task.current_timeline_version_id
        if not stale:
            try:
                original = CreationTaskObservationRequest.model_validate(start["arguments"]["payload"])
                _path, output, _binding = _registered_observation_output(workspace_id, task_id, original.target,
                    CreationExecutionActor.from_event(workspace_id, start))
                stale = output != start["input_facts"]["output"]
            except (KeyError, OSError, ValueError, PermissionError, HTTPException):
                stale = True
        observations.append({"job_id": job.id, "status": job.status,
            "stale": stale,
            "timeline_version_id": start["input_facts"]["base_version_id"], "result": result,
            "result_url": f"/api/creation-tasks/{task_id}/media-jobs/{job.id}"})
    targets = []
    try:
        _path, output, _binding = _registered_observation_output(workspace_id, task_id,
            CreationTaskObservationTarget(kind="final"), None)
    except (KeyError, OSError, ValueError, PermissionError, HTTPException):
        pass  # Missing/changed final is not an available observation target.
    else:
        targets.append({"target": {"kind": "final"}, "artifact_id": output["artifact_id"], "sha256": output["sha256"],
                        "output_role": "composed_output"})
    with production_repo._connect() as conn:
        rows = conn.execute("""SELECT a.id,a.logical_ref,a.kind,a.sha256,a.producer_job_id FROM artifact_records a
            JOIN job_runs j ON j.workspace_id=a.workspace_id AND j.id=a.producer_job_id
            JOIN task_events e ON e.workspace_id=j.workspace_id AND e.id='event_' || j.id || '_start'
            WHERE a.workspace_id=? AND a.task_id=? AND j.kind=? AND j.status='succeeded'
            AND json_extract(e.payload_json,'$.member_id')=?
            AND json_extract(e.payload_json,'$.input_facts.base_version_id') IS ?
            ORDER BY j.created_at DESC,a.id DESC LIMIT 10""",
            (workspace_id, task_id, TASK_MEDIA_KIND, _assistant_member_id(request, workspace_id), task.current_timeline_version_id)).fetchall()
    for row in rows:
        if row["logical_ref"].endswith(".mp4") or row["kind"] == "graphic_source" and row["logical_ref"].endswith(".png"):
            targets.append({"target": {"kind": "media_job", "job_id": row["producer_job_id"], "artifact_id": row["id"]},
                "artifact_id": row["id"], "sha256": row["sha256"],
                "output_role": "graphic_source" if row["kind"] == "graphic_source" else "composed_preview"})
    version = production_repo.get_timeline_version(workspace_id, task.current_timeline_version_id) if task.current_timeline_version_id else None
    return {"task_id": task_id, "timeline_version_id": task.current_timeline_version_id,
        "timeline_sequence": version.sequence if version else 0,
        "quality_check": current, "quality_history": [_bounded_quality_evidence(item)
            for item in quality_check_repo.history(workspace_id, task_id)],
        "observations": observations, "targets": targets, "targets_limit": 11,
        "media_policy": "local_measurements_and_text_only"}


@app.get("/api/creation-tasks/{task_id}/observations")
def get_creation_task_observations(task_id: str, request: Request):
    return _task_observation_facts(task_id, request)


@app.post("/api/creation-tasks/{task_id}/observations")
@_task_media_route("output_observation", "observation")
def observe_creation_task_output(task_id: str, request: Request, payload: CreationTaskObservationRequest):
    task, _member_id = _exact_edit_access(task_id, request, write=True)
    try:
        _observation_version(task, payload)
    except ValueError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    context = _task_media_grant_or_queue("output_observation")
    _context, job, event, actor = TASK_MEDIA_CONTEXT.get()
    path, output, binding = _registered_observation_output(task.workspace_id, task_id, payload.target, actor)
    from app.granted_subprocess import run_granted_command
    def run_command(command, *, output_paths=()):
        context.check()
        result = run_granted_command(context.scheduler, context.grant, command,
            timeout_seconds=max(.1, min(30., context.deadline_monotonic - time.monotonic())),
            max_stdout_bytes=MAX_OBSERVATION_BYTES, max_stderr_bytes=32 * 1024,
            output_paths=output_paths, max_output_file_bytes=context.max_output_bytes,
            cancel_event=context.cancel_event)
        if result.returncode:
            raise ValueError("本地实际输出采样失败，请检查媒体和工具")
        return result
    measured = observe_output(path, sample_times=payload.sample_times_seconds,
        temporary_root=settings.effective_temporary_root_path, run_command=run_command,
        expected_size=(output["registered_width"], output["registered_height"]),
        max_output_bytes=context.max_output_bytes,
        ocr_worker=Path(settings.native_ocr_worker_path).expanduser() if event["input_facts"]["ocr"]["status"] == "ready" else None)
    montage = binding.get("montage") or binding.get("media_input", {}).get("plan")
    single_clip = binding.get("media_input", {}).get("clip")
    for sample in measured["samples"]:
        timestamp = sample["timestamp_seconds"]
        if montage:
            sample["object_refs"] = [f"clip:{clip['id']}" for clip in montage.get("clips", [])
                if clip["timeline_start_seconds"] <= timestamp < clip["timeline_end_seconds"]]
            sample["object_refs"].extend(f"overlay:{overlay['id']}" for overlay in montage.get("graphic_overlays", [])
                if overlay["start_seconds"] <= timestamp < overlay["end_seconds"])
        elif single_clip:
            sample["object_refs"] = [f"clip:{single_clip['id']}"]
            sample["timeline_timestamp_seconds"] = single_clip["timeline_start_seconds"] + timestamp
    result = {"observation_id": job.id, "task_id": task_id, "timeline_version_id": event["input_facts"]["base_version_id"],
        "timeline_sequence": event["input_facts"]["timeline_sequence"], "observed_at": utc_now().isoformat(),
        "target": payload.target.model_dump(mode="json"), "ocr_execution": event["input_facts"]["ocr"], "output": {key: value for key, value in output.items()
            if key not in {"logical_ref", "mtime_ns", "ctime_ns"}}, "output_role": binding["kind"], **measured}
    return result


@app.get("/api/creation-tasks/{task_id}/media-jobs")
def list_task_media_jobs(task_id: str, request: Request, cursor: str | None = None, limit: int = 20):
    if not 1 <= limit <= 40:
        raise HTTPException(status_code=422, detail="媒体作业分页大小须为 1–40")
    actor = _require_permit_actor(request, current_workspace_id(request))
    runtime = _creation_runtime()
    media = runtime.registrations["creation_job"].owner.task_media
    _creation_task_or_404(actor.workspace_id, task_id)
    parameters = [actor.workspace_id, task_id, TASK_MEDIA_KIND, actor.member_id]
    before = ""
    if cursor is not None:
        try:
            saved, event = media.read(actor.workspace_id, cursor)
        except KeyError as exc:
            raise HTTPException(status_code=404, detail="媒体作业分页位置不存在") from exc
        if saved.task_id != task_id or CreationExecutionActor.from_event(actor.workspace_id, event) != actor:
            raise HTTPException(status_code=404, detail="媒体作业分页位置不存在")
        before = " AND (j.created_at < ? OR (j.created_at = ? AND j.id < ?))"
        parameters.extend([saved.created_at.isoformat(), saved.created_at.isoformat(), saved.id])
    parameters.append(limit + 1)
    with production_repo._connect() as conn:
        rows = conn.execute("SELECT j.* FROM job_runs j JOIN task_events e ON e.workspace_id=j.workspace_id "
            "AND e.job_id=j.id AND e.id='event_' || j.id || '_start' "
            "WHERE j.workspace_id=? AND j.task_id=? AND j.kind=? AND json_extract(e.payload_json,'$.member_id')=?" + before +
            " ORDER BY j.created_at DESC,j.id DESC LIMIT ?", parameters).fetchall()
    items = [_task_media_job_response(media, production_repo._job_run_from_row(row), actor, runtime) for row in rows[:limit]]
    return {"items": items, "next_cursor": rows[limit-1]["id"] if len(rows) > limit else None}


@app.get("/api/creation-tasks/{task_id}/media-jobs/{job_id}")
def get_task_media_job(task_id: str, job_id: str, request: Request):
    actor = _require_permit_actor(request, current_workspace_id(request))
    runtime = _creation_runtime()
    media = runtime.registrations["creation_job"].owner.task_media
    try:
        job, event = media.read(actor.workspace_id, job_id)
    except KeyError as exc:
        raise HTTPException(status_code=404, detail="任务媒体作业不存在") from exc
    if job.task_id != task_id:
        raise HTTPException(status_code=404, detail="任务媒体作业不存在")
    return _task_media_job_response(media, job, actor, runtime)


@app.post("/api/creation-tasks/{task_id}/media-jobs/{job_id}/cancel")
def cancel_task_media_job(task_id: str, job_id: str, request: Request):
    actor = _require_permit_actor(request, current_workspace_id(request))
    runtime = _creation_runtime()
    media = runtime.registrations["creation_job"].owner.task_media
    try:
        job, event = media.read(actor.workspace_id, job_id)
    except KeyError as exc:
        raise HTTPException(status_code=404, detail="任务媒体作业不存在") from exc
    from app.creation_execution import CreationExecutionActor
    if job.task_id != task_id or CreationExecutionActor.from_event(job.workspace_id, event) != actor:
        raise HTTPException(status_code=404, detail="任务媒体作业不存在")
    if job.status in {"queued", "running", "interrupted"}:
        with production_repo._connect() as conn:
            rows = conn.execute("SELECT id FROM device_work_requests WHERE workspace_id=? AND owner_id=? AND owner_type='creation_job' AND state IN ('waiting','blocked','granted','yield_requested')",
                                (job.workspace_id, job.id)).fetchall()
        for row in rows:
            runtime.scheduler.cancel(row["id"], actor)
            runtime.registrations["creation_job"].executor.request_cancel(row["id"])
        production_repo.finish_job_run(job.workspace_id, job.id, status="cancelled", failure_reason="user_cancelled",
            impact="当前时间线保持不变。", repair_action="需要时重新安排媒体处理。")
    return _task_media_job_response(media, job, actor, runtime)


@app.post("/api/creation-tasks/{task_id}/media-jobs/{job_id}/retry")
def retry_task_media_job(task_id: str, job_id: str, request: Request):
    actor = _require_permit_actor(request, current_workspace_id(request))
    runtime = _creation_runtime()
    media = runtime.registrations["creation_job"].owner.task_media
    try:
        job, event = media.read(actor.workspace_id, job_id)
    except KeyError as exc:
        raise HTTPException(status_code=404, detail="任务媒体作业不存在") from exc
    if job.task_id != task_id or CreationExecutionActor.from_event(job.workspace_id, event) != actor:
        raise HTTPException(status_code=404, detail="任务媒体作业不存在")
    reason = "result_invalid" if job.status=="succeeded" and not _task_media_outputs_current(job) else job.status
    if reason not in {"failed", "cancelled", "result_invalid"}:
        raise HTTPException(status_code=409, detail="只有失败或已取消的媒体作业可以显式重试")
    with production_repo._connect() as conn:
        saved = conn.execute("SELECT id FROM device_work_requests WHERE workspace_id=? AND owner_id=? AND owner_type='creation_job'",
                             (job.workspace_id, job.id)).fetchone()
    if saved is None:
        raise HTTPException(status_code=409, detail="媒体作业没有可核验的原设备请求")
    try:
        runtime.scheduler.retry_existing(saved["id"], actor, reason=reason)
    except PermissionError as exc:
        raise HTTPException(status_code=403, detail=str(exc)) from exc
    except ValueError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    runtime.wake()
    receipt = _task_media_job_response(media, job, actor, runtime)
    receipt["result"] = None
    return JSONResponse(status_code=202, content=receipt)


def _task_audio() -> TaskAudio:
    return TaskAudio(production_repo, artifact_store, settings.effective_temporary_root_path, picture_renderer=_render_task_picture_input)


def _effective_audio_timeline(plan: CreationTaskMontagePlan) -> AudioTimeline:
    return plan.audio_timeline or narration_audio_timeline(plan.narration_audio_path or "", plan.duration_seconds)


@app.post("/api/creation-tasks/{task_id}/audio/import")
@_task_media_route("audio_import", "audio_source")
def import_creation_task_audio(task_id: str, request: Request, audio: UploadFile = File(...)):
    workspace_id = current_workspace_id(request)
    _creation_task_or_404(workspace_id, task_id)
    suffix = Path(audio.filename or "").suffix.lower()
    if suffix not in {".wav", ".mp3", ".m4a", ".aac", ".flac"}:
        raise HTTPException(status_code=422, detail="请选择 WAV、MP3、M4A、AAC 或 FLAC 音频")
    try:
        record = _task_audio().publish(workspace_id, task_id, kind="audio_source", parameters={"name": Path(audio.filename or "音频").name[:120]},
                                      input_refs=[], operation="upload", media_input={"staged_input": audio.staged_input, "sha256": audio.source_sha256}, suffix=suffix)
        duration = _task_audio().probe(_task_audio().source(workspace_id, task_id, record.logical_ref))
    except (OSError, ValueError, subprocess.SubprocessError) as exc:
        raise HTTPException(status_code=422, detail="音频导入失败，请检查文件格式、时长及外接盘。") from exc
    return {"source_ref": record.logical_ref, "name": Path(audio.filename or "音频").name[:120], "duration_ms": round(duration*1000)}


@app.get("/api/creation-tasks/{task_id}/audio/recordings")
def list_creation_task_recordings(task_id: str, request: Request):
    workspace_id = current_workspace_id(request)
    task = _creation_task_or_404(workspace_id, task_id)
    if not task.confirmed_script_id:
        return {"items": []}
    service = _task_audio()
    current_narration_refs = set()
    if task.montage_plan_id:
        plan = creation_task_montage_plan_from_payload(
            production_repo.get_creation_task_montage_plan(workspace_id, task_id))
        if plan.script_id == task.confirmed_script_id:
            current_narration_refs = {clip.source_ref for track in _effective_audio_timeline(plan).tracks
                                      if track.role == "narration" for clip in track.clips}
    if task.narration_cache_key:
        current_narration = production_repo.get_narration_artifact(
            workspace_id, task.narration_cache_key,
        )
        if (current_narration is not None and current_narration.task_id == task.id
                and current_narration.script_id == task.confirmed_script_id
                and current_narration.source_kind == "recorded"
                and current_narration.source_artifact_ref):
            current_narration_refs.add(current_narration.source_artifact_ref)
    items = []
    for record in reversed(production_repo.list_artifact_records(workspace_id, task_id)):
        if record.kind != "task_recording":
            continue
        try:
            _, duration_ms = service.recording(
                workspace_id, task_id, record.logical_ref,
            )
            if not _task_media_outputs_current(production_repo.get_job_run(workspace_id, record.producer_job_id)):
                continue
        except (KeyError, ValueError, FileNotFoundError):
            continue  # Failed or obsolete uploads are never offered as current narration.
        items.append({"source_ref": record.logical_ref, "artifact_id": record.id,
                      "audio_url": f"/api/creation-tasks/{task_id}/audio/artifacts/{record.id}",
                      "duration_ms": duration_ms, "created_at": record.created_at.isoformat(),
                      "applied": record.logical_ref in current_narration_refs})
    return {"items": items}


@app.post("/api/creation-tasks/{task_id}/audio/recordings")
@_task_media_route("recording_save", "recording")
def save_creation_task_recording(task_id: str, request: Request, audio: UploadFile = File(...)):
    workspace_id = current_workspace_id(request)
    task = _creation_task_or_404(workspace_id, task_id)
    if task.stage not in {"narration", "montage", "review"} or not task.confirmed_script_id:
        raise HTTPException(status_code=409, detail="请先确认当前任务文案，再保存电脑录音")
    script_digest = production_repo.confirmed_creation_task_script_digest(
        workspace_id, task.id, task.confirmed_script_id,
    )
    if script_digest is None:
        raise HTTPException(status_code=409, detail="当前文案未确认或已经变化，不能保存为本任务录音")
    suffix = Path(audio.filename or "").suffix.lower()
    if suffix not in {".webm", ".mp4", ".m4a", ".ogg", ".wav"}:
        raise HTTPException(status_code=422, detail="当前录音格式不可用，请使用 WebM、MP4、Ogg 或 WAV")

    try:
        service = _task_audio()
        record = service.publish(
            workspace_id, task_id, kind="task_recording",
            parameters={"script_id": task.confirmed_script_id,
                        "script_digest": script_digest,
                        "montage_plan_id": task.montage_plan_id},
            input_refs=[], operation="upload", media_input={"staged_input": audio.staged_input, "sha256": audio.source_sha256}, suffix=suffix,
        )
        duration_ms = round(service.probe(service.source(workspace_id, task_id, record.logical_ref)) * 1000)
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=f"电脑录音未保存：{exc}") from exc
    except (KeyError, OSError, subprocess.SubprocessError) as exc:
        raise HTTPException(status_code=422, detail="电脑录音未保存，请检查录音格式和本地存储") from exc
    return {"source_ref": record.logical_ref, "artifact_id": record.id,
            "audio_url": f"/api/creation-tasks/{task_id}/audio/artifacts/{record.id}",
            "duration_ms": duration_ms, "applied": False}


@app.post(
    "/api/creation-tasks/{task_id}/audio/recordings/adopt",
    response_model=CreationTaskNarrationResponse,
)
def adopt_creation_task_recording(
    task_id: str,
    request: Request,
    payload: CreationTaskRecordingAdoptRequest,
) -> CreationTaskNarrationResponse:
    workspace_id = current_workspace_id(request)
    task = _creation_task_or_404(workspace_id, task_id)
    if task.stage != "narration" or task.stage_status not in {"not_started", "failed"}:
        raise HTTPException(status_code=409, detail="当前任务不能首次采用录音")
    if task.confirmed_script_id != payload.script_id:
        raise HTTPException(status_code=409, detail="文案版本已变化，请重新选择当前录音")
    try:
        script = production_repo.get_creation_task_script(workspace_id, payload.script_id)
    except KeyError as exc:
        raise HTTPException(status_code=404, detail="当前文案不存在") from exc
    if script.selection_status != "confirmed" or len(script.sections) != 1:
        raise HTTPException(status_code=409, detail="当前版本有多个文案段，暂不能确定单段录音的对应关系")
    section = script.sections[0]
    if payload.source_section_id != section.id:
        raise HTTPException(status_code=409, detail="录音对应的文案段已变化，请重新选择")
    script_digest = production_repo.confirmed_creation_task_script_digest(
        workspace_id, task.id, script.id,
    )
    if script_digest is None:
        raise HTTPException(status_code=409, detail="当前文案未确认或已经变化，不能采用录音")
    try:
        source, duration_ms = _task_audio().recording(
            workspace_id, task.id, payload.source_ref,
        )
        if not _task_media_outputs_current(production_repo.get_job_run(workspace_id, source.producer_job_id)):
            raise ValueError("电脑录音已变化或缺少受许可核验回执，请重新录制")
        audio_path = _task_audio().source(workspace_id, task.id, source.logical_ref)
        cache_seed = f"recorded:{task.id}:{script.id}:{section.id}:{source.logical_ref}:{source.sha256}"
        cache_key = f"recorded_{hashlib.sha256(cache_seed.encode('utf-8')).hexdigest()[:48]}"
        narration_ref = production_repo.narration_artifact_reference(cache_key)
        narration_id = f"narration_segment_{hashlib.sha256(cache_seed.encode('utf-8')).hexdigest()[:20]}"
        language = {"zh-CN": "zh", "en-US": "en", "zh-CN/en-US": "zh-en"}[script.language]
        record = NarrationArtifactRecord(
            id=cache_key,
            workspace_id=workspace_id,
            task_id=task.id,
            script_id=script.id,
            voice_profile_id=None,
            cache_key=cache_key,
            audio_path=str(audio_path),
            duration_seconds=duration_ms / 1000,
            sample_rate=None,
            model_id=None,
            language=language,
            source_kind="recorded",
            source_artifact_ref=source.logical_ref,
            source_sha256=source.sha256,
            source_script_digest=script_digest,
        )
        segment = NarrationSegment(
            id=narration_id,
            workspace_id=workspace_id,
            task_id=task.id,
            script_id=script.id,
            source_section_id=section.id,
            text=section.content,
            audio_reference=narration_ref,
            duration_seconds=duration_ms / 1000,
            sample_rate=None,
            model_id=None,
            voice_profile_id=None,
            voice_version=None,
            language=language,
            pronunciation_version="",
            status="ready",
            source_kind="recorded",
            source_artifact_ref=source.logical_ref,
            source_sha256=source.sha256,
            source_script_digest=script_digest,
        )
        task, record = production_repo.complete_creation_task_narration(record, segments=[segment])
    except (KeyError, ValueError, FileNotFoundError) as exc:
        raise HTTPException(status_code=409, detail=f"当前录音未采用：{exc}") from exc
    return _creation_task_narration_response(task, record)


def _require_task_media_artifact(record, request):
    job = production_repo.get_job_run(record.workspace_id, record.producer_job_id)
    if job.kind != TASK_MEDIA_KIND:
        return
    actor = _require_permit_actor(request, record.workspace_id)
    runtime = _creation_runtime()
    media = runtime.registrations["creation_job"].owner.task_media
    original, event = media.read(record.workspace_id, job.id)
    if CreationExecutionActor.from_event(record.workspace_id, event) != actor or media.verify_identity(actor) != "ready":
        raise KeyError(record.id)
    if original.status != "succeeded" or not _task_media_outputs_current(original):
        raise KeyError(record.id)
    if record.kind not in {"audio_source", "task_recording"} and media.check(original, event, actor) != "ready":
        raise KeyError(record.id)


@app.get("/api/creation-tasks/{task_id}/audio/artifacts/{artifact_id}")
def get_creation_task_audio_artifact(task_id: str, artifact_id: str, request: Request):
    workspace_id = current_workspace_id(request)
    _creation_task_or_404(workspace_id, task_id)
    try:
        record = production_repo.get_artifact_record(workspace_id, artifact_id)
        if record.task_id != task_id:
            raise KeyError(artifact_id)
        _require_task_media_artifact(record, request)
        path = _task_audio().source(workspace_id, task_id, record.logical_ref, actor=_require_permit_actor(request, workspace_id))
    except (KeyError, ValueError, FileNotFoundError, PermissionError) as exc:
        raise HTTPException(status_code=404, detail="当前任务的音频不存在") from exc
    audio_media_types = {".wav": "audio/wav", ".webm": "audio/webm", ".ogg": "audio/ogg",
                         ".m4a": "audio/mp4", ".mp4": "audio/mp4"}
    return FileResponse(path, media_type=audio_media_types.get(path.suffix))


@app.get("/api/creation-tasks/{task_id}/audio/waveform/{clip_id}")
@_task_media_route("audio_waveform", "waveform")
def get_creation_task_audio_waveform(task_id: str, clip_id: str, request: Request):
    workspace_id = current_workspace_id(request)
